// CORBA IDL scanner-evaluation fixture (MFI-21.4).
module Brokerage {
  enum Side { BUY, SELL };
  struct Order { string symbol; Side side; long quantity; };
  exception Rejected { string reason; };
  interface Account {
    string place(in Order order) raises (Rejected);
    void cancel(in string orderId);
    void Cancel(in long orderNumber);
  };
};
